#Requires -Version 5.1
# feat-informe-pdf-obras.ps1
# Informe PDF imprimible desde el listado de Obras.
#
# ARCHIVOS:
# 1. src/app/obras/page.tsx (MODIFICADO)
#    - Botón "Informe PDF" junto a "Nueva obra"
#    - Estado generandoPdf + searchQuery
#    - handleGenerarPdf: filtra por archivedFilter + estadoFilter + searchQuery,
#      llama a /api/informes/obras y descarga el PDF
#    - prop onSearch en DataTable para capturar el texto de búsqueda en tiempo real
#
# 2. src/components/shared/DataTable.tsx (MODIFICADO)
#    - Nueva prop onSearch?: (query: string) => void
#    - Se llama cada vez que el usuario escribe o limpia la búsqueda
#
# 3. src/app/api/informes/obras/route.ts (NUEVO)
#    - POST /api/informes/obras
#    - Recibe: obras (array ya filtrado), archivedFilter, estadoFilterLabel, searchQuery
#    - Genera PDF A4 horizontal con jsPDF + jspdf-autotable + LOGO_BASE64
#    - Columnas: Cliente | Obra (negrita) | Estado (coloreado) | N.º Presupuesto | Anotaciones
#    - Anotaciones: celda vacía con fondo azul claro para escritura manual
#    - Cabecera repetida en cada página (showHead: "everyPage")
#    - Filas no se cortan entre páginas (rowPageBreak: "avoid")
#    - Numeración de páginas correcta (dos pasadas para totalPages real)
#    - Si obras.length === 0: devuelve 400 con mensaje de error

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> feat: informe PDF obras" -ForegroundColor Cyan

Write-Host "  -> src\app\obras\page.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\obras\page.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\obras\page.tsx"), $bytes)
Write-Host "  OK: 11 KB" -ForegroundColor Green

Write-Host "  -> src\components\shared\DataTable.tsx" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\components\shared\DataTable.tsx")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\components\shared\DataTable.tsx"), $bytes)
Write-Host "  OK: 11 KB" -ForegroundColor Green

Write-Host "  -> src\app\api\informes\obras\route.ts" -ForegroundColor Gray
$dir = Split-Path -Parent (Join-Path $RepoPath "src\app\api\informes\obras\route.ts")
if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\api\informes\obras\route.ts"), $bytes)
Write-Host "  OK: 8 KB" -ForegroundColor Green

$page = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\obras\page.tsx"), [System.Text.Encoding]::UTF8)
$route = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\api\informes\obras\route.ts"), [System.Text.Encoding]::UTF8)
$dt = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\components\shared\DataTable.tsx"), [System.Text.Encoding]::UTF8)
if ($page.Contains("handleGenerarPdf"))    { Write-Host "  OK: handleGenerarPdf en obras/page.tsx" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($page.Contains('"Informe PDF"'))       { Write-Host "  OK: boton Informe PDF" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($route.Contains("jspdf-autotable"))    { Write-Host "  OK: API route con autotable" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($route.Contains("ANOTACIONES"))       { Write-Host "  OK: columna Anotaciones" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($dt.Contains("onSearch"))             { Write-Host "  OK: DataTable onSearch" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
Write-Host ""
Write-Host "  git add -A"
Write-Host '  git commit -m "feat: informe PDF obras con filtros, busqueda y columna Anotaciones"'
Write-Host "  git push"
